CREATE TYPE "Role" AS ENUM ('USER','TECHNICIAN','ADMIN');
CREATE TYPE "TicketStatus" AS ENUM ('NEW','IN_PROGRESS','WAITING_FOR_USER','RESOLVED','CLOSED','CANCELLED');
CREATE TYPE "Priority" AS ENUM ('LOW','NORMAL','HIGH','URGENT');
CREATE TYPE "MessageVisibility" AS ENUM ('PUBLIC','INTERNAL');
CREATE TYPE "NotificationType" AS ENUM ('TICKET_CREATED','TICKET_ASSIGNED','STATUS_CHANGED','NEW_MESSAGE','WAITING_FOR_USER','TICKET_RESOLVED','TICKET_REOPENED','TICKET_CLOSED');
CREATE TABLE "User" ("id" UUID PRIMARY KEY,"email" TEXT NOT NULL UNIQUE,"name" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"role" "Role" NOT NULL DEFAULT 'USER',"organization" TEXT,"department" TEXT,"isActive" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Category" ("id" UUID PRIMARY KEY,"name" TEXT NOT NULL UNIQUE,"isActive" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE SEQUENCE "Ticket_number_seq";
CREATE TABLE "Ticket" ("id" UUID PRIMARY KEY,"number" INTEGER NOT NULL DEFAULT nextval('"Ticket_number_seq"'),"subject" TEXT NOT NULL,"description" TEXT NOT NULL,"priority" "Priority" NOT NULL DEFAULT 'NORMAL',"status" "TicketStatus" NOT NULL DEFAULT 'NEW',"requesterId" UUID NOT NULL,"assigneeId" UUID,"categoryId" UUID NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,"resolvedAt" TIMESTAMP(3),"closedAt" TIMESTAMP(3));
CREATE UNIQUE INDEX "Ticket_number_key" ON "Ticket"("number"); CREATE INDEX "Ticket_status_createdAt_idx" ON "Ticket"("status","createdAt"); CREATE INDEX "Ticket_requesterId_createdAt_idx" ON "Ticket"("requesterId","createdAt"); CREATE INDEX "Ticket_assigneeId_status_idx" ON "Ticket"("assigneeId","status"); CREATE INDEX "Ticket_categoryId_idx" ON "Ticket"("categoryId");
CREATE TABLE "TicketMessage" ("id" UUID PRIMARY KEY,"ticketId" UUID NOT NULL,"authorId" UUID NOT NULL,"body" TEXT NOT NULL,"visibility" "MessageVisibility" NOT NULL DEFAULT 'PUBLIC',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE INDEX "TicketMessage_ticketId_createdAt_idx" ON "TicketMessage"("ticketId","createdAt");
CREATE TABLE "TicketAttachment" ("id" UUID PRIMARY KEY,"ticketId" UUID NOT NULL,"uploaderId" UUID NOT NULL,"originalName" TEXT NOT NULL,"objectKey" TEXT NOT NULL UNIQUE,"mimeType" TEXT NOT NULL,"size" INTEGER NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE INDEX "TicketAttachment_ticketId_idx" ON "TicketAttachment"("ticketId");
CREATE TABLE "TicketAssignment" ("id" UUID PRIMARY KEY,"ticketId" UUID NOT NULL,"fromAssigneeId" UUID,"toAssigneeId" UUID,"actorId" UUID NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE INDEX "TicketAssignment_ticketId_createdAt_idx" ON "TicketAssignment"("ticketId","createdAt");
CREATE TABLE "TicketStatusHistory" ("id" UUID PRIMARY KEY,"ticketId" UUID NOT NULL,"fromStatus" "TicketStatus","toStatus" "TicketStatus" NOT NULL,"actorId" UUID NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE INDEX "TicketStatusHistory_ticketId_createdAt_idx" ON "TicketStatusHistory"("ticketId","createdAt");
CREATE TABLE "Notification" ("id" UUID PRIMARY KEY,"userId" UUID NOT NULL,"ticketId" UUID,"type" "NotificationType" NOT NULL,"readAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE INDEX "Notification_userId_readAt_createdAt_idx" ON "Notification"("userId","readAt","createdAt");
CREATE TABLE "TelegramConnection" ("id" UUID PRIMARY KEY,"userId" UUID NOT NULL UNIQUE,"chatId" TEXT NOT NULL UNIQUE,"linkedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "TelegramLinkToken" ("id" UUID PRIMARY KEY,"userId" UUID NOT NULL,"tokenHash" TEXT NOT NULL UNIQUE,"expiresAt" TIMESTAMP(3) NOT NULL,"usedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE INDEX "TelegramLinkToken_userId_expiresAt_idx" ON "TelegramLinkToken"("userId","expiresAt");
CREATE TABLE "AuditLog" ("id" UUID PRIMARY KEY,"actorId" UUID,"action" TEXT NOT NULL,"entityType" TEXT NOT NULL,"entityId" TEXT,"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE INDEX "AuditLog_entityType_entityId_createdAt_idx" ON "AuditLog"("entityType","entityId","createdAt"); CREATE INDEX "AuditLog_actorId_createdAt_idx" ON "AuditLog"("actorId","createdAt");
ALTER TABLE "Ticket" ADD CONSTRAINT "Ticket_requesterId_fkey" FOREIGN KEY("requesterId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "Ticket" ADD CONSTRAINT "Ticket_assigneeId_fkey" FOREIGN KEY("assigneeId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE; ALTER TABLE "Ticket" ADD CONSTRAINT "Ticket_categoryId_fkey" FOREIGN KEY("categoryId") REFERENCES "Category"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "TicketMessage" ADD CONSTRAINT "TicketMessage_ticketId_fkey" FOREIGN KEY("ticketId") REFERENCES "Ticket"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "TicketMessage" ADD CONSTRAINT "TicketMessage_authorId_fkey" FOREIGN KEY("authorId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "TicketAttachment" ADD CONSTRAINT "TicketAttachment_ticketId_fkey" FOREIGN KEY("ticketId") REFERENCES "Ticket"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "TicketAttachment" ADD CONSTRAINT "TicketAttachment_uploaderId_fkey" FOREIGN KEY("uploaderId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "TicketAssignment" ADD CONSTRAINT "TicketAssignment_ticketId_fkey" FOREIGN KEY("ticketId") REFERENCES "Ticket"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "TicketStatusHistory" ADD CONSTRAINT "TicketStatusHistory_ticketId_fkey" FOREIGN KEY("ticketId") REFERENCES "Ticket"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Notification" ADD CONSTRAINT "Notification_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Notification" ADD CONSTRAINT "Notification_ticketId_fkey" FOREIGN KEY("ticketId") REFERENCES "Ticket"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "TelegramConnection" ADD CONSTRAINT "TelegramConnection_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
